import client from "../client";
import clientMultipart from "../clientMultipart";

const saccoStaffAction = (data) => {
    return client.post("/saccos/staff", data);
};
const saccoMemberAction = (data) => {
    return client.post("/saccos/member", data);
};

const registerUserAction = (data) => {
    return clientMultipart.post("/saccos/members/register", data);
};  

export default {
     saccoStaffAction,
    registerUserAction,
  saccoMemberAction
};